from pages import foreword,glance,reading,cards,end,sources,build,covart,verse
from fig import strip,svg
from fig3 import *
PG.configure('/sixteen-samskaras/',[('','The Sixteen Saṃskāras','The Rites That Mark a Hindu Life')],'navy','The Sixteen Saṃskāras','Lord','Saṃskāras')
PG.CFG.update(backurl='/hymns/',backname='Hymns and Mantras')
PG.OUT='outp/sixteen-samskaras/'
P2=lambda a,b: fig_row(a,b,[''] * len(b),gy=160)
def S(id,n,name,eng,fig,when,done,mean,today,k,tk=None):
    return reading(id,f'{n} · {name.upper()}',eng,fig,[f'<b>When.</b> {when}',f'<b>What is done.</b> {done}',f'<b>Meaning.</b> {mean}',f'<b>Today.</b> {today}'],tk,k)
i=0
LIST=['Garbhādhāna','Puṃsavana','Sīmantonnayana','Jātakarma','Nāmakaraṇa','Niṣkramaṇa','Annaprāśana','Cūḍākaraṇa','Karṇavedha','Vidyārambha','Upanayana','Vedārambha','Keśānta','Samāvartana','Vivāha','Antyeṣṭi']
pp=[foreword(i,['A Hindu life is marked, from before birth to after death, by rites called <b>saṃskāras</b>: the naming of a baby, the first rice, the first haircut, the first letters, the sacred thread, marriage, and the last rites.','This article explains all sixteen of the classical list, one by one: when each is done, what is done, what it means, and how it lives on today. Searches like “what is nāmakaraṇa”, “annaprāśana meaning” or “why upanayana” all lead here.'],[('z','Sixteen ceremonies in one life?'),('b','In the classical list. Most families today keep six or seven of them, often combined. But the idea behind them is worth knowing whole.')]),
 glance([('Word','Saṃskāra: refining, perfecting, as a gem is polished'),('Number','Lists vary: 40 in the Gautama Dharmasūtra, 16 in the familiar list'),('Source','The Gṛhyasūtras (household ritual manuals), Dharmaśāstra, custom'),('Stages','Before birth (3), childhood (6), learning (5), marriage (1), death (1)'),('Most kept today','Nāmakaraṇa, annaprāśana, cūḍākaraṇa, akṣarābhyāsa, upanayana, vivāha, antyeṣṭi'),('Purpose','To sanctify each stage and shape the person')],svg(560,150,'A life from cradle to old age',g(80,140,1,cradle())+g(180,140,1,child())+g(270,140,1.2,person('#1d6fb8'))+g(360,140,1.1,person('#c0392b'))+g(450,140,1.2,sage('#ff8c1a')))),
 reading('word','WHAT IS A SAṂSKĀRA','Refining a life',svg(560,150,'A rough stone and a polished gem',g(200,110,1,'<path d="M-30 0 l10 -30 l30 -6 l24 20 l-8 22z" fill="#8a8a8a"/>')+'<path d="M260 90 h40" stroke="#111" stroke-width="2" marker-end="none"/><path d="M296 84 l8 6 l-8 6z" fill="#111"/>'+g(370,110,1,'<path d="M-24 -20 h48 l12 14 l-36 36 l-36 -36z" fill="#5ab0e0"/>')),['<b>The word.</b> Saṃskāra comes from saṃ-kṛ, “to make well, to perfect”. It is the same root as Sanskrit (saṃskṛta, “refined”).','<b>Two senses.</b> In philosophy saṃskāras are the impressions our actions leave in the mind; in ritual, they are rites that leave good impressions at key moments.','<b>The idea.</b> As a gem is cut and polished, a person is shaped by being marked, welcomed and taught at each stage.','<b>Social too.</b> Each rite also announces a new stage to family and community: born, named, schooled, married, gone.'],[('z','So it’s like a polishing ceremony for a person?'),('b','Exactly that image is used in the texts. Each rite takes off a little roughness and brings out a little shine.')],'A rite that <b>refines a life</b>.'),
 reading('number','HOW MANY?','Forty, sixteen, or fewer',fig_row('Books of the household rites',[(books_stack(),1.4),(book(),1.4),(book(),1.4)],['','',''],gy=None),['<b>Forty.</b> The Gautama Dharmasūtra lists forty outer saṃskāras, including the great annual sacrifices.','<b>Eight inner ones.</b> The same text adds eight virtues of the self, and says they matter more than the forty rites; see the page on them below.','<b>Sixteen.</b> The familiar list of sixteen comes from later tradition based on the Gṛhyasūtras; the exact sixteen differ from list to list.','<b>Our list.</b> We follow the most common sixteen: from Garbhādhāna to Antyeṣṭi.'],None,'Lists vary; <b>sixteen</b> is the familiar one.'),
 cards('list','THE SIXTEEN AT A GLANCE','From before birth to after death',svg(560,60,'Sixteen dots along a line','<path d="M20 30 h520" stroke="#111" stroke-width="2"/>'+''.join(f'<circle cx="{30+j*33}" cy="30" r="9" fill="{["#f4a6b8","#e0a800","#1d6fb8","#c0392b","#555"][0 if j<3 else 1 if j<9 else 2 if j<14 else 3 if j<15 else 4]}"/>' for j in range(16))),[('🤰','Before birth','1 Garbhādhāna · 2 Puṃsavana · 3 Sīmantonnayana'),('👶','Childhood','4 Jātakarma · 5 Nāmakaraṇa · 6 Niṣkramaṇa · 7 Annaprāśana · 8 Cūḍākaraṇa · 9 Karṇavedha'),('📚','Learning','10 Vidyārambha · 11 Upanayana · 12 Vedārambha · 13 Keśānta · 14 Samāvartana'),('🔥','Marriage and death','15 Vivāha · 16 Antyeṣṭi')],None,'<b>Sixteen</b> steps across a life.'),
 S('garbhadhana','1','Garbhādhāna','The rite of conception',svg(560,150,'A couple before a sacred fire',g(200,140,1.1,person('#1d6fb8'))+g(280,140,1.2,agni())+g(360,140,1.1,person('#c0392b'))),'After marriage, when a couple wish for a child.','Prayers and offerings asking for a healthy, worthy child; the texts give mantras for it. It is private by nature.','Conception is treated as sacred, not merely biological; the child is wished for and welcomed in advance.','Rarely performed as a formal rite; its spirit survives in prayers for a child, often at temples or on vows like Putradā Ekādaśī.','A child <b>wished for and prayed for</b>.'),
 S('pumsavana','2','Puṃsavana','For the unborn child',svg(560,150,'An expectant mother with a banyan sprig',g(240,140,1.3,mother())+g(360,140,.9,tree())),'Around the third month of pregnancy.','Prayers and offerings; the Gṛhyasūtras describe giving the mother the juice of a banyan shoot.','The name means “quickening a male”, and the texts frankly ask for a son. That reflects its age.','Where kept, families now treat it as a prayer for a healthy child of either sex; it is often combined with sīmanta.','A prayer <b>for the child within</b>.',[('z','It asks for a son? Seriously?'),('b','Frankly, yes: the ancient wording does. Most families who keep it today simply pray for a healthy baby.')]),
 S('simanta','3','Sīmantonnayana','The parting of the hair',svg(560,150,'A mother with bangles, surrounded by women',g(280,140,1.3,mother())+g(180,140,1,person('#e0a800'))+g(380,140,1,person('#7a3fa0'))),'In the later months of pregnancy, often the seventh or eighth.','In the texts the husband parts his wife’s hair with a porcupine quill and sacred twig while songs are sung; she is honoured and protected.','Care for the mother and her mind: she is kept happy and free of fear, which the tradition held good for the child.','Very much alive as the <b>sīmanta</b> or baby-shower: bangles, flowers, sweets and blessings from the women of the family (valaikāppu in Tamil Nadu, sīmanta in Karnataka).','The mother <b>honoured and protected</b>.'),
 S('jatakarma','4','Jātakarma','The birth rite',svg(560,150,'A father touching honey to a baby’s lips',g(240,140,1.2,person('#1d6fb8'))+g(330,140,1.6,baby())+g(420,130,1.2,pot('#e0a800'))),'At birth, before the cord is cut in the old texts.','The father gives the baby a touch of honey and ghee, traditionally with a gold spoon, and whispers into the ear; the texts include “vāk” (speech) and prayers for intelligence and long life.','Welcoming the child with sweetness, speech and blessing in the very first moments.','A touch of honey (often today with a gold ring) and a whispered name of God survive in many families.','The first taste <b>is sweet</b>.'),
 S('namakarana','5','Nāmakaraṇa','The naming',svg(560,150,'A baby in a decorated cradle',g(280,145,1.5,cradle())+g(150,140,1,mother())+g(410,140,1,person('#1d6fb8'))),'Usually on the tenth, eleventh or twelfth day after birth.','The name is announced, often whispered first into the baby’s right ear; a priest or elder may suggest names by the birth star.','A name is identity and blessing: many names are names of God, so every call is a remembrance.','One of the most kept. In many Karnataka homes the naming is celebrated with the baby placed in a decorated cradle for the first time, with songs.','A name <b>that is a blessing</b>.'),
 S('nishkramana','6','Niṣkramaṇa','The first outing',svg(560,150,'A parent holding a baby up to the sun',g(200,80,1.3,sun())+g(320,140,1.2,person('#c0392b'))+g(330,90,1.2,baby())),'In the third or fourth month.','The baby is taken out of the house for the first time and shown the sun (and in some texts the moon), often to a temple.','Introducing the child to the wider world and its light.','Often kept quietly as the first temple visit.','The child <b>meets the sun</b>.'),
 S('annaprashana','7','Annaprāśana','The first rice',svg(560,150,'A baby being fed the first rice',g(220,140,1.2,mother())+g(300,130,1.4,baby())+g(390,140,1.4,pot_rice())),'Around the sixth month, when solid food begins.','The baby is fed a little cooked rice, pāyasa or ghee-rice, often offered first to God.','Food as sacred: the first solid food is prasāda.','Widely kept. In Kerala it is <b>coroonu</b> (cōṟūṇ), famously at <a href="/temples-of-india/kerala/guruvayur/">Guruvāyūr</a>; many families do it at a temple.','The first food <b>is prasāda</b>.',[('z','Why rice?'),('b','Rice is the staple of so much of India, and a symbol of plenty. Wheat-eating regions use other first foods.')]),
 S('chudakarana','8','Cūḍākaraṇa','The first haircut',svg(560,150,'A child and scissors',g(240,140,1.3,child())+g(340,130,1.6,scissors())),'In the first or third year, sometimes the fifth.','The child’s first hair is shaved; traditionally a tuft (śikhā) was left. The hair is often offered at a temple.','Removing the hair of birth; a fresh start and an offering of self.','Very common as <b>muṇḍana</b> or mokku: thousands of children have their first tonsure at Tirupati and other temples.','The first hair <b>offered</b>.'),
 S('karnavedha','9','Karṇavedha','Ear-piercing',svg(560,150,'An ear with a gold ring',g(280,140,2,ear())),'Between the first and fifth year, or earlier.','The ears are pierced, traditionally with a gold needle, and earrings put in; for boys and girls alike in the old texts.','Protection and adornment; some explain it as health-giving. (Interpretation.)','Common for girls everywhere and for boys in many South Indian families.','A <b>golden protection</b>.'),
 S('vidyarambha','10','Vidyārambha','The first letters',svg(560,150,'A child writing letters in a plate of rice',g(240,140,1.2,child())+g(360,140,1.4,slate())),'Around the fifth year, often on Vijayadaśamī.','The child writes the first letters, often in a plate of rice with a finger or a gold ring, guided by a parent or teacher; Gaṇeśa and Sarasvatī are worshipped.','Learning begins as worship; the teacher is honoured.','Widely kept as <b>akṣarābhyāsa</b>; in Kerala as Vidyārambham on Vijayadaśamī. See our <a href="/festivals/navaratri/">Navarātri</a> series.','Learning <b>begins as worship</b>.'),
 S('upanayana','11','Upanayana','The sacred thread',svg(560,150,'A boy receiving the sacred thread from a teacher before the fire',g(200,140,1.2,sage('#ff8c1a'))+g(290,140,1.1,agni())+g(380,140,1.2,child())+g(380,120,.8,thread())),'Traditionally between the eighth and twelfth year; the Gṛhyasūtras give different ages for the three twice-born varṇas.','The child is “led near” (upa-nayana) a teacher, invested with the sacred thread (yajñopavīta), and given the Gāyatrī mantra; he begins brahmacarya, the student life.','A second birth, into learning and spiritual life; hence the word dvija, “twice-born”.','Still widely kept in many communities, often in the teens or just before marriage. Historically it was restricted by varṇa and, in later texts, to boys; some early texts speak of women scholars who had it, a point still debated.','The <b>second birth</b>.',[('z','Why is it called a second birth?'),('b','The first is from your mother; the second, the texts say, is from the teacher and the Gāyatrī: birth into learning.')]),
 S('vedarambha','12','Vedārambha','Beginning the Veda',svg(560,150,'A student before a teacher with a book',g(220,140,1.2,sage('#ff8c1a'))+g(360,140,1.1,child())+g(290,120,1.2,book())),'Soon after upanayana.','Formal study of one’s branch of the Veda begins with the teacher.','Learning as a lifelong discipline.','Some lists merge it into upanayana; in Vedic pāṭhaśālās it remains a real beginning.','Study <b>begins in earnest</b>.'),
 S('keshanta','13','Keśānta','The first shave',svg(560,150,'A young man and a cow',g(220,140,1.2,person('#1d6fb8'))+g(360,140,.9,cow())),'Around the sixteenth year.','The first shave of the beard; in the texts the student gives a cow to his teacher, hence its other name, godāna.','Coming of age within student life.','Rarely kept as a separate rite.','<b>Coming of age</b>.'),
 S('samavartana','14','Samāvartana','The return home',svg(560,150,'A young man bathing and leaving the teacher’s home',g(200,140,1.2,sage('#ff8c1a'))+g(330,140,1.2,person('#1d6fb8'))+river(560,140)),'At the end of studentship.','A ceremonial bath (hence snātaka, “one who has bathed”); new clothes; leave of the teacher with a gift (gurudakṣiṇā) and his final charge.','Graduation: the student is ready to return to society and marry.','Often folded into the wedding as a short rite; universities in India still echo it in convocation.','<b>Graduation day</b>.'),
 verse('charge','The teacher’s final charge','Taittirīya Upaniṣad 1.11',['vedamanūcyācāryo’ntevāsinamanuśāsti','satyaṃ vada | dharmaṃ cara | svādhyāyānmā pramadaḥ','devapitṛkāryābhyāṃ na pramaditavyam','mātṛdevo bhava | pitṛdevo bhava','ācāryadevo bhava | atithidevo bhava'],svg(200,140,'A teacher blessing a student',g(70,130,1.1,sage('#ff8c1a'))+g(140,130,1,person('#1d6fb8'))),'Having taught the Veda, the teacher instructs the pupil: Speak the truth. Practise dharma. Do not neglect your study. Do not neglect your duties to the gods and ancestors. Treat your mother as God; your father as God; your teacher as God; your guest as God.',[('satyaṃ vada','speak the truth'),('dharmaṃ cara','practise dharma'),('svādhyāyāt mā pramadaḥ','do not neglect study'),('mātṛ-devaḥ bhava','let your mother be God to you'),('ācārya-devaḥ','teacher as God'),('atithi-devaḥ','guest as God')],'This is the oldest convocation address in India, given at samāvartana. Its lines are now national mottos and school mottos; “atithidevo bhava” is India’s tourism slogan.',k='<b>Speak truth, practise dharma</b>.',note='Lines selected from the passage; text checked against the sanskritdocuments.org edition of the Śīkṣāvallī.'),
 S('vivaha','15','Vivāha','Marriage',svg(560,160,'A couple taking seven steps around the fire',g(280,140,1.2,agni())+g(200,140,1.1,person('#c0392b'))+g(360,140,1.1,person('#1d6fb8'))+g(330,155,1,steps7())),'Adulthood, after studentship.','Many rites, varying by region: kanyādāna (the bride given by her father), pāṇigrahaṇa (taking her hand), circling the sacred fire, and the saptapadī, seven steps taken together, after which the marriage is complete; in the south, tying the maṅgalasūtra.','The central saṃskāra: entering the householder stage, the support of all the others.','Kept by almost every Hindu family, in endless regional forms.','Seven steps, <b>one life together</b>.',[('z','Which step makes them married?'),('b','In the texts, the seventh step of the saptapadī. In much of the south, people treat the maṅgalasūtra as the moment.')]),
 S('antyeshti','16','Antyeṣṭi','The last rites',svg(560,150,'A lamp and a quiet fire',g(220,140,1.4,lamp())+g(340,140,1.2,flames())),'At death.','The body is bathed, dressed, carried and cremated with prayers, the eldest son or a close relative lighting the fire; rites follow over the next days and the first year.','The “last sacrifice”: the body is offered to the fire, and the departed is helped onward.','Universally kept. See our <a href="/festivals/pitru-paksha/after-death/">After death</a> and <a href="/festivals/pitru-paksha/">Pitṛ Pakṣa</a> articles.','The <b>last offering</b>.'),
 cards('inner','THE EIGHT INNER SAṂSKĀRAS','Virtues over rites',svg(560,70,'Eight small lamps',''.join(g(40+j*68,60,1,lamp()) for j in range(8))),[('💗','Dayā','Compassion for all beings.'),('🌿','Kṣānti','Patience, forbearance.'),('🤝','Anasūyā','Freedom from envy.'),('💧','Śauca','Purity, inner and outer.'),('😌','Anāyāsa','Ease; not straining oneself or others.'),('✨','Maṅgala','Auspicious, good conduct.'),('🎁','Akārpaṇya','Generosity; not being miserly.'),('🕊️','Aspṛhā','Freedom from greed.')],[('z','So rites without virtues don’t count?'),('b','That’s what Gautama says, bluntly: the one with the virtues but few rites reaches the goal; the one with all forty rites and no virtues does not.')],'The <b>inner</b> rites matter more.',intro='The Gautama Dharmasūtra, after listing forty rites, adds eight “virtues of the self” and says these, not the rites alone, bring one to Brahman.'),
 reading('women','SAṂSKĀRAS AND WOMEN','A frank note',svg(560,150,'A girl writing first letters',g(240,140,1.2,child())+g(360,140,1.4,slate())),['<b>In later texts.</b> Most childhood rites were done for girls without Vedic mantras, and marriage was treated as the main saṃskāra for a woman.','<b>Earlier evidence.</b> Some texts speak of women Vedic scholars (brahmavādinīs) who had upanayana; how widespread this was is debated.','<b>Today.</b> Naming, first rice, first haircut, ear-piercing and first letters are usually done for daughters exactly as for sons.','<b>Our view.</b> We report the history as it is and leave each family to its own practice.'],None,'History told <b>plainly</b>.'),
 reading('today','WHICH ARE KEPT TODAY','The living core',fig_row('Cradle, rice, scissors, slate, thread, fire',[(cradle(),.8),(pot_rice(),1.2),(scissors(),1.2),(slate(),1),(thread(),1),(agni(),1.1)],['naming','first rice','first hair','letters','thread','marriage'],gy=160),['<b>Almost everywhere.</b> Nāmakaraṇa, annaprāśana, vivāha and antyeṣṭi.','<b>Very common.</b> Sīmanta, cūḍākaraṇa (muṇḍana), karṇavedha, akṣarābhyāsa.','<b>In many communities.</b> Upanayana.','<b>Rare.</b> Garbhādhāna, puṃsavana, niṣkramaṇa as formal rites, keśānta, samāvartana and vedārambha as separate rites.'],None,'Seven or eight <b>still widely kept</b>.'),
 reading('meaning','WHAT THEY ADD UP TO','A life made sacred',svg(560,150,'A path from cradle to lamp',g(90,140,.9,cradle())+'<path d="M140 120 q140 -60 280 0" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="6 5"/>'+g(470,130,1.4,lamp())),['<b>Every stage marked.</b> No stage of life is left ordinary: conception, birth, food, hair, learning, marriage, death.','<b>Family and community.</b> Each rite gathers people around the person; you are never alone at the turning points.','<b>A rhythm of gratitude.</b> Each rite offers the new stage to God before living it.','<b>Inner and outer.</b> With Gautama’s eight virtues, the rites aim at a refined person, not just a ritual record.'],[('z','So the whole life is a pūjā?'),('b','That’s the vision. Read our <a href="/home-puja/">home pūjā</a> article and you’ll see the same pattern: welcome, serve, offer, receive.')],'A whole life <b>offered</b>.'),
 end(i,['<b>Saṃskāra.</b> A rite that refines a life at each stage.','<b>Before birth.</b> Garbhādhāna, puṃsavana, sīmanta.','<b>Childhood.</b> Birth, naming, outing, first rice, first hair, ear-piercing.','<b>Learning.</b> Letters, thread, Veda, first shave, graduation.','<b>Life and death.</b> Marriage and the last rites; and eight inner virtues above all.'],'Read next: our <a href="/home-puja/">simple home pūjā</a>, step by step.','The sixteen saṃskāras'),
 sources([('Overview:','Wikipedia, “Samskara (rite of passage)” (forty in the Gautama Dharmasūtra; sixteen in later Gṛhya tradition); Encyclopaedia Britannica, “samskara”; Korada Subrahmanyam, “Sixteen Saṃskāras” (e-PG Pathshala).'),('Verse:','Taittirīya Upaniṣad 1.11, sanskritdocuments.org (Śīkṣāvallī).')],'the exact sixteen differ between lists; ages and details differ between Gṛhyasūtras and regions; the extent of upanayana for women in early times.','Our own summaries; regional customs named as examples, not rules.')]
build(i,'LIFE RITES · FROM BIRTH TO DEATH',covart('A cradle, a slate, a sacred fire and a lamp',g(80,196,1.3,cradle())+g(170,196,1.5,slate())+g(260,196,1.6,agni())+g(350,196,1.6,lamp())+g(220,80,1.2,steps7())),'The rites that mark a Hindu life','What a <b>saṃskāra</b> is, then all <b>sixteen</b> one by one: when, what is done, <b>what it means</b>, and how it lives on today.','The sixteen saṃskāras of Hindu tradition explained: what a saṃskāra is, then each rite from garbhādhāna and nāmakaraṇa to annaprāśana, upanayana, vivāha and antyeṣṭi, with when it is done, what is done, its meaning and how it is kept today.',pp)
print('samskara ok')
